int _foodLogEstimateSize(
  FoodLog object,
  List<int> offsets,
  Map<Type, List<int>> allOffsets,
) {
  var bytesCount = offsets.last;
  bytesCount += 3 + object.dateKey.length * 3;
  bytesCount += 3 + object.foodName.length * 3;
  bytesCount += 3 + object.unit.length * 3;
  return bytesCount;
}

void _foodLogSerialize(
  FoodLog object,
  IsarWriter writer,
  List<int> offsets,
  Map<Type, List<int>> allOffsets,
) {
  writer.writeDouble(offsets[0], object.calories);
  writer.writeDouble(offsets[1], object.carbs);
  writer.writeString(offsets[2], object.dateKey);
  writer.writeDouble(offsets[3], object.fat);
  writer.writeString(offsets[4], object.foodName);
  writer.writeDouble(offsets[5], object.protein);
  writer.writeDouble(offsets[6], object.quantity);
  writer.writeDateTime(offsets[7], object.timestamp);
  writer.writeString(offsets[8], object.unit);
}

FoodLog _foodLogDeserialize(
  Id id,
  IsarReader reader,
  List<int> offsets,
  Map<Type, List<int>> allOffsets,
) {
  final object = FoodLog();
  object.calories = reader.readDouble(offsets[0]);
  object.carbs = reader.readDouble(offsets[1]);
  object.dateKey = reader.readString(offsets[2]);
  object.fat = reader.readDouble(offsets[3]);
  object.foodName = reader.readString(offsets[4]);
  object.id = id;
  object.protein = reader.readDouble(offsets[5]);
  object.quantity = reader.readDouble(offsets[6]);
  object.timestamp = reader.readDateTime(offsets[7]);
  object.unit = reader.readString(offsets[8]);
  return object;
}

P _foodLogDeserializeProp<P>(
  IsarReader reader,
  int propertyId,
  int offset,
  Map<Type, List<int>> allOffsets,
) {
  switch (propertyId) {
    case 0:
      return (reader.readDouble(offset)) as P;
    case 1:
      return (reader.readDouble(offset)) as P;
    case 2:
      return (reader.readString(offset)) as P;
    case 3:
      return (reader.readDouble(offset)) as P;
    case 4:
      return (reader.readString(offset)) as P;
    case 5:
      return (reader.readDouble(offset)) as P;
    case 6:
      return (reader.readDouble(offset)) as P;
    case 7:
      return (reader.readDateTime(offset)) as P;
    case 8:
      return (reader.readString(offset)) as P;
    default:
      throw IsarError('Unknown property with id $propertyId');
  }
}

